import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;

public class MoneyDemo {
    public static void main(String[] args) {
        double d = 0.0;
        for (int i = 0; i < 10; i++) {
            d += 0.1;
        }
        System.out.println("double sum of ten times 0.1 = " + d);
        System.out.println("double 0.1 + 0.2 = " + (0.1 + 0.2));

        BigDecimal b = BigDecimal.ZERO;
        for (int i = 0; i < 10; i++) {
            b = b.add(new BigDecimal("0.1"));
        }
        System.out.println("BigDecimal sum = " + b);
        System.out.println("new BigDecimal(0.1) = " + new BigDecimal(0.1));
        BigDecimal one = new BigDecimal("1.0");
        BigDecimal oneTwo = new BigDecimal("1.00");
        System.out.println("equals 1.0 vs 1.00: " + one.equals(oneTwo)
                + ", compareTo: " + one.compareTo(oneTwo));
        BigDecimal x = new BigDecimal("2.345");
        System.out.println("2.345 HALF_UP = " + x.setScale(2, RoundingMode.HALF_UP)
                + ", HALF_EVEN = " + x.setScale(2, RoundingMode.HALF_EVEN));

        Instant when = Instant.parse("2026-03-31T23:30:00Z");
        System.out.println("Instant              = " + when);
        ZoneOffset ist = ZoneOffset.ofHoursMinutes(5, 30);
        System.out.println("as OffsetDateTime IST= " + when.atOffset(ist));
        LocalDateTime naive = LocalDateTime.ofInstant(when, ZoneId.of("UTC"));
        System.out.println("LocalDateTime (UTC)  = " + naive + "  (no zone information)");
        ZoneId kolkata = ZoneId.of("Asia/Kolkata");
        System.out.println("local date in Kolkata= " + when.atZone(kolkata).toLocalDate());
    }
}

