CREATE OR REPLACE FUNCTION dept_payroll(p_dept integer) RETURNS numeric
LANGUAGE sql STABLE AS $$
  SELECT coalesce(sum(salary), 0) FROM employees WHERE dept_id = p_dept
$$;

CREATE OR REPLACE FUNCTION raise_salary(p_emp integer, p_pct numeric) RETURNS numeric
LANGUAGE plpgsql AS $$
DECLARE v_new numeric;
BEGIN
  IF p_pct <= 0 OR p_pct > 50 THEN
    RAISE EXCEPTION 'invalid percentage: %', p_pct USING ERRCODE = '22023';
  END IF;
  UPDATE employees SET salary = round(salary * (1 + p_pct / 100), 2)
  WHERE emp_id = p_emp RETURNING salary INTO v_new;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee % not found', p_emp;
  END IF;
  RETURN v_new;
END $$;

