CREATE OR REPLACE PROCEDURE archive_payments(p_batch integer)
LANGUAGE plpgsql AS $$
DECLARE v_moved integer;
BEGIN
  LOOP
    WITH moved AS (
      DELETE FROM payments WHERE payment_id IN
        (SELECT payment_id FROM payments ORDER BY payment_id LIMIT p_batch)
      RETURNING *)
    INSERT INTO payments_archive SELECT * FROM moved;
    GET DIAGNOSTICS v_moved = ROW_COUNT;
    EXIT WHEN v_moved = 0;
    COMMIT;                                   -- release locks, make progress durable
  END LOOP;
END $$;

