CREATE TABLE emp_audit (
  audit_id   bigserial PRIMARY KEY,
  emp_id     integer, old_salary numeric, new_salary numeric,
  changed_at timestamptz DEFAULT now()
);

CREATE OR REPLACE FUNCTION trg_salary_audit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.salary IS DISTINCT FROM OLD.salary THEN
    INSERT INTO emp_audit (emp_id, old_salary, new_salary)
    VALUES (OLD.emp_id, OLD.salary, NEW.salary);
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER employees_salary_audit
AFTER UPDATE OF salary ON employees
FOR EACH ROW EXECUTE FUNCTION trg_salary_audit();

