import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

public class ProxyDemo {
    interface OrderService {
        void placeOrder(String id);
        void audit(String id);
    }

    static final List<String> log = new ArrayList<>();

    static class OrderServiceImpl implements OrderService {
        public void placeOrder(String id) {
            log.add("placeOrder body: " + id);
            audit(id);                 // self-invocation: plain call on this, bypasses the proxy
        }
        public void audit(String id) {
            log.add("audit body: " + id);
        }
    }

    public static void main(String[] args) {
        OrderService target = new OrderServiceImpl();
        InvocationHandler tx = (proxy, method, a) -> {
            log.add("BEGIN before " + method.getName());
            try {
                Object r = method.invoke(target, a);
                log.add("COMMIT after " + method.getName());
                return r;
            } catch (java.lang.reflect.InvocationTargetException e) {
                log.add("ROLLBACK after " + method.getName());
                throw e.getCause();
            }
        };
        OrderService svc = (OrderService) Proxy.newProxyInstance(
            OrderService.class.getClassLoader(), new Class<?>[] {OrderService.class}, tx);

        svc.placeOrder("A1");          // external call: goes through the proxy
        log.add("---");
        svc.audit("A1");               // direct external call to the second method
        log.forEach(System.out::println);
    }
}

import java.io.IOException;
import java.util.concurrent.Callable;

public class RollbackRule {
    static String run(Callable<Void> work) {
        try {
            work.call();
            return "COMMIT";
        } catch (RuntimeException | Error e) {
            return "ROLLBACK (unchecked: " + e.getClass().getSimpleName() + ")";
        } catch (Exception e) {
            return "COMMIT (checked: " + e.getClass().getSimpleName()
                + " does not roll back by default)";
        }
    }

    public static void main(String[] args) {
        System.out.println(run(() -> { throw new IllegalStateException("x"); }));
        System.out.println(run(() -> { throw new IOException("x"); }));
        System.out.println(run(() -> { throw new StackOverflowError(); }));
        System.out.println(run(() -> null));
    }
}

@Service
public class TransferService {
    private final AccountRepository accounts;
    private final AuditService audit;           // a separate bean: calls pass through its proxy

    public TransferService(AccountRepository accounts, AuditService audit) {
        this.accounts = accounts;
        this.audit = audit;
    }

    @Transactional(rollbackFor = Exception.class, timeout = 5)
    public void transfer(long from, long to, BigDecimal amount) throws InsufficientFunds {
        long first = Math.min(from, to), second = Math.max(from, to);
        accounts.lockInOrder(first, second);              // SELECT ... FOR UPDATE ORDER BY id
        if (accounts.debit(from, amount) == 0) {                  // guarded atomic UPDATE
            audit.record("REJECTED", from, to, amount);   // REQUIRES_NEW: survives rollback
            throw new InsufficientFunds(from);            // checked; rollbackFor covers it
        }
        accounts.credit(to, amount);
    }
}

