import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

public class Ring {
    static long hash(String s) throws Exception {
        byte[] d = MessageDigest.getInstance("MD5").digest(s.getBytes(StandardCharsets.UTF_8));
        return ((d[0] & 0xFFL) << 24) | ((d[1] & 0xFFL) << 16)
             | ((d[2] & 0xFFL) << 8) | (d[3] & 0xFFL);
    }
    static TreeMap<Long, String> build(List<String> nodes, int vnodes) throws Exception {
        TreeMap<Long, String> ring = new TreeMap<>();
        for (String n : nodes) for (int v = 0; v < vnodes; v++) ring.put(hash(n + "#" + v), n);
        return ring;
    }
    static String owner(TreeMap<Long, String> ring, String key) throws Exception {
        Map.Entry<Long, String> e = ring.ceilingEntry(hash(key));
        return (e != null ? e : ring.firstEntry()).getValue();
    }
    public static void main(String[] args) throws Exception {
        int keys = 100_000;
        for (int vn : new int[] {1, 16, 256}) {
            TreeMap<Long, String> ring = build(List.of("A", "B", "C"), vn);
            Map<String, Integer> cnt = new TreeMap<>();
            for (int i = 0; i < keys; i++) cnt.merge(owner(ring, "user:" + i), 1, Integer::sum);
            System.out.println("vnodes=" + vn + " load=" + cnt);
        }
        TreeMap<Long, String> before = build(List.of("A", "B", "C"), 256);
        TreeMap<Long, String> after = build(List.of("A", "B", "C", "D"), 256);
        int moved = 0, movedMod = 0;
        List<String> n3 = List.of("A", "B", "C"), n4 = List.of("A", "B", "C", "D");
        for (int i = 0; i < keys; i++) {
            String k = "user:" + i;
            if (!owner(before, k).equals(owner(after, k))) moved++;
            if (!n3.get((int) (hash(k) % 3)).equals(n4.get((int) (hash(k) % 4)))) movedMod++;
        }
        System.out.printf("ring, add node D: %d of %d keys moved (%.1f%%)%n",
            moved, keys, 100.0 * moved / keys);
        System.out.printf("hash mod N, 3 to 4 nodes: %d of %d keys moved (%.1f%%)%n",
            movedMod, keys, 100.0 * movedMod / keys);
        Map<String, Integer> hot = new TreeMap<>();
        Random r = new Random(1);
        TreeMap<Long, String> ring = build(List.of("A", "B", "C", "D"), 256);
        for (int i = 0; i < keys; i++) {
            String k = r.nextInt(100) < 30 ? "user:celebrity" : "user:" + r.nextInt(50_000);
            hot.merge(owner(ring, k), 1, Integer::sum);
        }
        System.out.println("hot key 30% of requests: " + hot);
    }
}

