import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Stampede {
    static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    static final ConcurrentHashMap<String, CompletableFuture<String>> inflight =
        new ConcurrentHashMap<>();
    static final AtomicInteger dbHits = new AtomicInteger();

    static String loadFromDb(String key) {
        dbHits.incrementAndGet();
        try { Thread.sleep(200); } catch (InterruptedException e) { throw new RuntimeException(e); }
        return "value-of-" + key;
    }
    static String naive(String key) {
        String v = cache.get(key);
        if (v == null) { v = loadFromDb(key); cache.put(key, v); }
        return v;
    }
    static String singleFlight(String key) {
        String v = cache.get(key);
        if (v != null) return v;
        CompletableFuture<String> f = inflight.computeIfAbsent(key, k ->
            CompletableFuture.supplyAsync(() -> {
                String x = loadFromDb(k); cache.put(k, x); return x;
            }).whenComplete((x, t) -> inflight.remove(k)));
        return f.join();
    }
    static int run(boolean safe) throws Exception {
        cache.clear(); dbHits.set(0);
        ExecutorService pool = Executors.newFixedThreadPool(100);
        CountDownLatch go = new CountDownLatch(1);
        for (int i = 0; i < 100; i++) {
            pool.submit(() -> { go.await(); return safe ? singleFlight("hot") : naive("hot"); });
        }
        go.countDown(); pool.shutdown(); pool.awaitTermination(10, TimeUnit.SECONDS);
        return dbHits.get();
    }
    public static void main(String[] a) throws Exception {
        System.out.println("100 concurrent requests, key just expired");
        System.out.println("naive cache-aside:   database loads = " + run(false));
        System.out.println("single-flight:       database loads = " + run(true));
    }
}

